import {createGame,throwDart,nextTurn,leaderboard,clone} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='zero-club-v1';let storageError=false,db;
try{db=JSON.parse(localStorage.getItem(KEY))||{version:1,players:[],history:[],game:null,undo:[]};validateBackup(db);}catch{db={version:1,players:[],history:[],game:null,undo:[]};storageError=true;}
let view=db.game?'game':'setup',multi=1,target=321,roster=[{id:crypto.randomUUID(),name:''},{id:crypto.randomUUID(),name:''}],challenge={enabled:true,exercise:'Pompes',multiplier:1,cap:0},toastTimer,offlineReady=false;
const exercises=['Pompes','Squats','Abdos','Burpees','Fentes alternées','Jumping jacks','Montées de genoux'];
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{storageError=true;notify('Sauvegarde impossible sur cet appareil. Exporte tes données.');}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(html){const m=$('#modal');m.innerHTML=html;if(!m.open)m.showModal();}
function closeModal(){$('#modal').close();}
function header(){return `<header class="header"><button class="brand" data-action="home" aria-label="ZERO CLUB, accueil"><span class="brandmark">Z</span>ZERO CLUB<small>DARTS & FRIENDS</small></button><nav class="nav" aria-label="Navigation"><button class="${['setup','game'].includes(view)?'active':''}" data-view="${db.game?'game':'setup'}">Jouer</button><button class="${view==='ranking'?'active':''}" data-view="ranking">Classement</button><button class="${view==='history'?'active':''}" data-view="history">Historique</button></nav></header>`;}
function footer(){return `<footer class="footer"><span id="offline-status">${offlineReady?'Prêt pour le hors-ligne':'Données sur cet appareil'}</span><button data-action="rules">Règles & installation</button><button data-action="data">Mes données</button></footer>`;}
function render(){const app=$('#app');app.innerHTML=`<div class="shell ${view==='game'?'game-page':''}">${header()}${view==='setup'?setup():view==='game'?gameView():view==='ranking'?ranking():historyView()}${storageError?'<div class="warning" role="alert">Le stockage est indisponible ou illisible. Les données de cette session risquent de ne pas être conservées. Exporte-les avant de fermer.</div>':''}${footer()}</div>`;}
function setup(){return `<div class="page-title"><div><span class="eyebrow">La prochaine revanche commence ici</span><h1>On se fait une partie ?</h1></div><span class="pill">Règles maison</span></div><div class="setup-grid"><section class="target-panel"><span class="eyebrow">01 / Choisis ta cible</span><div class="target-tabs" role="group" aria-label="Score cible">${[150,321,501].map(n=>`<button class="${n===target?'selected':''}" aria-pressed="${n===target}" data-target="${n}">${n}</button>`).join('')}</div><div class="giant">${target}</div><div class="target-bottom"><strong>PILE. OU RIEN.</strong><span>Atteins ${target} points.<br>Évite le retour à zéro.</span></div></section><section class="panel"><div class="section-head"><h2>02 / Le casting</h2><small>${roster.length} joueur${roster.length>1?'s':''}</small></div><div class="roster">${roster.map((p,i)=>`<div class="roster-row"><span class="avatar">${String(i+1).padStart(2,'0')}</span><input data-player="${i}" aria-label="Nom du joueur ${i+1}" maxlength="30" autocomplete="off" placeholder="Joueur ${i+1}" value="${esc(p.name)}"><button class="iconbtn" data-remove="${i}" aria-label="Retirer le joueur ${i+1}" ${roster.length===1?'disabled':''}>×</button></div>`).join('')}</div><button class="textbtn" data-action="add-player">+ Ajouter un joueur</button>${db.players.some(p=>!roster.some(r=>r.id===p.id))?`<div class="saved">${db.players.filter(p=>!roster.some(r=>r.id===p.id)).map(p=>`<button class="chip" data-saved="${p.id}">+ ${esc(p.name)}</button>`).join('')}</div>`:''}<div class="challenge-settings"><label class="switchrow">Les défis du club<input type="checkbox" id="challenge-enabled" ${challenge.enabled?'checked':''} aria-label="Activer les défis sportifs"></label>${challenge.enabled?`<div class="fields"><label>Exercice<select id="exercise">${exercises.map(e=>`<option ${e===challenge.exercise?'selected':''}>${e}</option>`).join('')}<option ${!exercises.includes(challenge.exercise)?'selected':''} value="custom">Personnalisé</option></select></label><label>Intensité<select id="intensity">${[.5,1,2].map(n=>`<option value="${n}" ${n===challenge.multiplier?'selected':''}>× ${n.toLocaleString('fr')}</option>`).join('')}</select></label></div>${!exercises.includes(challenge.exercise)?`<label class="hint">Nom de l’exercice<input id="custom-exercise" class="field" maxlength="40" value="${esc(challenge.exercise)}"></label>`:''}<p class="hint">Bordure = répétitions de la volée. Au sol = le double. Exemple : 21 points, puis bordure = ${Math.ceil(21*challenge.multiplier)} ${esc(challenge.exercise.toLowerCase())}.</p><label class="hint">Plafond par défi (0 = sans plafond)<input class="field" id="cap" type="number" min="0" max="1000" step="1" value="${challenge.cap}"></label>`:'<p class="hint">Juste les fléchettes. Bordure et fléchette au sol valent 0 point.</p>'}</div><button class="primary start" data-action="start">C’est parti</button></section></div><div class="rule-strip"><article><b>01</b><div><strong>Trois fléchettes. À toi de jouer.</strong><p>Saisis chaque lancer, même les ratés.</p></div></article><article><b>02</b><div><strong>Le même score ? Retour à zéro.</strong><p>Rejoins un adversaire : son score s’efface.</p></div></article><article><b>03</b><div><strong>Un peu trop loin ? Ça se paie.</strong><p>Tu dépasses la cible : le lancer est soustrait.</p></div></article></div>`;}
function gameView(){const g=db.game;if(!g){view='setup';return setup();}const p=g.players[g.current],done=g.darts.length===3,locked=done||g.winner||g.pendingChallenge;return `<div class="page-title"><div><span class="eyebrow">Objectif ${g.target} / Manche ${g.round}</span><h1>${g.winner?'La partie est à toi.':'À toi de jouer.'}</h1></div><button class="secondary" data-action="new">Nouvelle partie</button></div><div class="game-grid"><div><section class="arena"><span class="eyebrow">${g.winner?'Victoire':'Au lancer'}</span><h2 class="break">${esc(p.name)}</h2><div class="score">${p.score}</div><span class="remaining">${g.target-p.score} points pour gagner</span><div class="track" role="progressbar" aria-valuenow="${p.score}" aria-valuemin="0" aria-valuemax="${g.target}" aria-label="Score de ${esc(p.name)}"><i style="width:${p.score/g.target*100}%"></i></div><div class="darts">${[0,1,2].map(i=>{const d=g.darts[i];return `<div class="dart ${d?'filled':''}"><small>LANCER ${i+1}</small>${d?d.kind==='rim'?'Bord':d.kind==='ground'?'Sol':d.kind==='miss'?'Raté':`${d.overflow?'−':'+'}${d.points}`:'—'}</div>`;}).join('')}</div></section><div class="players">${g.players.map((q,i)=>`<div class="player-score ${i===g.current?'current':''}"><span class="avatar">${String(i+1).padStart(2,'0')}</span><span class="name">${esc(q.name)}<small>${q.kills} remise${q.kills>1?'s':''} à zéro</small></span><strong>${q.score}</strong></div>`).join('')}</div></div><section class="panel keypad"><div class="section-head"><h2>${g.winner?'Bien joué !':done?'Volée terminée':`Fléchette ${g.darts.length+1} / 3`}</h2><small>${g.turnPoints} pts lancés</small></div><div class="multipliers" role="group" aria-label="Multiplicateur">${[1,2,3].map((n,i)=>`<button data-multi="${n}" class="${multi===n?'selected':''}" aria-pressed="${multi===n}" ${locked?'disabled':''}>${['Simple','Double','Triple'][i]} <span>×${n}</span></button>`).join('')}</div><div class="numbers">${Array.from({length:20},(_,i)=>`<button data-hit="${i+1}" aria-label="${multi} fois ${i+1}, ${(i+1)*multi} points" ${locked?'disabled':''}>${i+1}</button>`).join('')}</div><div class="specials"><button class="bull" data-bull="1" ${locked?'disabled':''}>Bull <small>25 points</small></button><button class="bull" data-bull="2" ${locked?'disabled':''}>Double bull <small>50 points</small></button><button data-kind="miss" ${locked?'disabled':''}>Raté · 0</button><button class="rim" data-kind="rim" ${locked?'disabled':''}>Bordure${g.challenge.enabled?' · défi':' · 0'}</button><button class="rim ground" data-kind="ground" ${locked?'disabled':''}>Au sol${g.challenge.enabled?' · défi ×2':' · 0'}</button></div><div class="turn-actions"><button class="secondary" data-action="undo" ${!db.undo?.length?'disabled':''}>Annuler</button>${g.winner?'<button class="primary" data-action="winner">Voir la victoire</button>':g.pendingChallenge?'<button class="primary" data-action="challenge">Voir le défi</button>':`<button class="primary" data-action="next" ${!done?'disabled':''}>${g.players.length===1?'Volée suivante':'Joueur suivant'}</button>`}</div><div class="feed"><h3>Derniers lancers</h3>${g.log.length?g.log.slice(-4).reverse().map(d=>`<div class="feed-item"><span>${esc(d.player)} · ${d.kind==='rim'?'Bordure':d.kind==='ground'?'Au sol':d.kind==='miss'?'Raté':`${d.multiplier===3?'T':d.multiplier===2?'D':'S'}${d.base}`}${d.victims.length?`<br><b class="danger">${esc(d.victims.join(', '))} à zéro</b>`:''}</span><b>${d.before} ${d.overflow?'−':'+'} ${d.points} = ${d.after}</b></div>`).join(''):'<p class="hint">Les scores se règlent ici. Les comptes, sur la cible.</p>'}</div></section></div>`;}
function ranking(){const rows=leaderboard(db.players,db.history).filter(p=>p.games);return `<div class="page-title"><div><span class="eyebrow">Les comptes sont faits</span><h1>Le classement.</h1></div><span class="pill">${db.history.length} partie${db.history.length>1?'s':''}</span></div><section class="panel">${rows.length?`<div class="board-head"><span>#</span><span>Joueur</span><span>Victoires</span><span>Parties</span><span>RàZ</span></div>${rows.map((p,i)=>`<div class="rank-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><strong>${esc(p.name)}</strong><span>${p.wins}</span><span>${p.games}</span><span>${p.kills}</span></div>`).join('')}<p class="hint">Tri par victoires, puis par remises à zéro infligées (RàZ). Parties terminées uniquement, tous modes confondus.</p>`:empty('Le trône est libre.','Termine une première partie pour lancer le classement.')}</section>`;}
function empty(title,description){return `<div class="empty"><div class="empty-mark">Ø</div><h2>${title}</h2><p>${description}</p><button class="secondary" data-view="${db.game?'game':'setup'}">${db.game?'Reprendre la partie':'Préparer une partie'}</button></div>`;}
const date=s=>new Date(s).toLocaleDateString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
function historyView(){return `<div class="page-title"><div><span class="eyebrow">Les belles victoires. Les gros retours à zéro.</span><h1>Dans les annales.</h1></div></div>${db.history.length?db.history.slice().reverse().map(g=>`<button class="history-card" data-history="${g.id}"><span><span class="eyebrow">${date(g.finishedAt)}</span><br><strong>${esc(g.players.find(p=>p.id===g.winner)?.name||'Joueur')} a gagné</strong><p>${g.players.length} joueur${g.players.length>1?'s':''} · ${g.round} manche${g.round>1?'s':''}</p></span><span class="mode">${g.target}</span></button>`).join(''):`<section class="panel">${empty('Tout reste à jouer.','Tes parties terminées et leurs lancers apparaîtront ici.')}</section>`}`;}
function start(){const names=new Set();const players=[];for(let i=0;i<roster.length;i++){let name=roster[i].name.trim()||`Joueur ${i+1}`;const key=name.toLocaleLowerCase('fr');if(names.has(key)){notify('Choisis des noms différents pour chaque joueur.');return;}names.add(key);const existing=db.players.find(p=>p.name.toLocaleLowerCase('fr')===key);players.push({id:existing?.id||roster[i].id,name});}for(const p of players){if(!db.players.some(q=>q.id===p.id))db.players.push(p);}db.game=createGame(players,target,clone(challenge));db.undo=[];multi=1;view='game';save();render();window.scrollTo({top:0,behavior:'smooth'});}
function snapshot(){db.undo??=[];db.undo.push(clone(db.game));}
function play(input){try{const result=throwDart(db.game,input);snapshot();db.game=result.game;multi=1;if(db.game.winner&&!db.history.some(g=>g.id===db.game.id))db.history.push(clone(db.game));save();render();const d=result.event;if(d.victims.length){impact(d.victims);notify(`${d.victims.join(', ')} : retour à zéro !`);}else if(d.overflow)notify(`Dépassement : ${d.before} − ${d.points} = ${d.after}`);if(db.game.pendingChallenge)showChallenge();if(db.game.winner)showWinner();}catch(e){notify(e.message);}}
function impact(names){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const e=document.createElement('div');e.className='impact';const b=document.createElement('b');b.textContent='RETOUR\nÀ ZÉRO.';b.style.whiteSpace='pre-line';const s=document.createElement('span');s.textContent=names.join(' & ');e.append(b,s);$('#effects').append(e);setTimeout(()=>e.remove(),1550);}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<50;i++){const e=document.createElement('i');e.className='confetti';e.style.left=Math.random()*100+'%';e.style.setProperty('--drift',Math.random()*240-120+'px');e.style.animationDelay=Math.random()*.6+'s';e.style.background=['#c2fa38','#ff715c','#f3f5eb'][i%3];$('#effects').append(e);setTimeout(()=>e.remove(),3400);}}
function showWinner(){const g=db.game;if(!g?.winner)return;const p=g.players.find(q=>q.id===g.winner);modal(`<div class="win-content"><span class="eyebrow">${g.target} pile. Respect.</span><div class="winner-label">VICTOIRE.</div><h2 class="break">${esc(p.name)}</h2><p>${p.throws} fléchettes · ${p.kills} remise${p.kills>1?'s':''} à zéro<br>La revanche se prépare déjà.</p><button class="primary" data-action="rematch">La revanche · mêmes joueurs</button><div class="modal-actions"><button class="secondary" data-action="undo-win">Corriger le dernier lancer</button><button class="secondary" data-action="close">Voir les scores</button></div></div>`);confetti();}
function showChallenge(){const c=db.game?.pendingChallenge;if(!c)return;modal(`<span class="eyebrow">${c.kind==='ground'?'Au sol. Défi doublé.':'La bordure a parlé'}</span><h2 class="break">${esc(c.player)}, à toi.</h2><div class="modal-number">${c.repetitions}</div><h2>${esc(c.exercise.toLowerCase())}</h2><p>Calcul : ${db.game.turnPoints} points lancés dans cette volée × ${db.game.challenge.multiplier.toLocaleString('fr')}${c.kind==='ground'?' (arrondi au supérieur), puis × 2':''}${db.game.challenge.cap?`, plafond ${db.game.challenge.cap}`:''}. ${c.repetitions===0?'Aucun point avant la bordure : aucun exercice cette fois.':''}</p><p class="hint">Chacun adapte le défi à ses capacités. Il reste facultatif.</p><div class="modal-actions"><button class="secondary" data-action="skip-challenge">Passer</button><button class="primary" data-action="finish-challenge">C’est fait</button></div>`);}
function undo(){if(!db.undo?.length)return;const current=db.game;db.game=db.undo.pop();db.history=db.history.filter(g=>g.id!==current.id);multi=1;closeModal();save();render();notify('Dernière action annulée.');}
function newGame(){if(db.game&&!db.game.winner){modal('<h2>Quitter cette partie ?</h2><p>Cette partie en cours sera abandonnée. Les joueurs et les parties terminées restent enregistrés.</p><div class="modal-actions"><button class="secondary" data-action="close">Continuer à jouer</button><button class="primary" data-action="abandon">Quitter la partie</button></div>');}else resetSetup();}
function resetSetup(){if(db.game){roster=db.game.players.map(p=>({id:p.id,name:p.name}));target=db.game.target;challenge=clone(db.game.challenge);}db.game=null;db.undo=[];view='setup';closeModal();save();render();}
function rules(){modal(`<span class="eyebrow">Le règlement du club</span><h2>Vos règles, au point près.</h2><p><b>Objectif :</b> partir de 0 et atteindre exactement 150, 321 ou 501. Trois fléchettes par tour. La victoire est immédiate, sans obligation de double.</p><p><b>Retour à zéro :</b> après chaque lancer qui marque des points, si ton nouveau score est celui d’un adversaire, il retombe à 0. Tous les adversaires à ce score sont concernés, y compris après une soustraction. Un raté, une bordure ou une fléchette au sol ne remet personne à zéro.</p><p><b>Dépassement :</b> seule la fléchette qui dépasse est soustraite. À 318, un 15 te ramène à 303. Les fléchettes suivantes restent jouables.</p><p><b>Défi :</b> une bordure vaut 0 et déclenche les répétitions calculées sur les points lancés jusqu’ici dans cette volée, y compris les lancers en dépassement. Une fléchette tombée au sol vaut aussi 0 : elle déclenche le double des répétitions de la bordure (après arrondi). Chaque bordure ou chute déclenche un nouveau défi. Si un plafond est défini, il s’applique au total final, même doublé. Le cumul repart à zéro au joueur suivant.</p><h2>Sur ton écran d’accueil.</h2><p>Sur iPhone, ouvre le site dans Safari, puis le menu Partager et « Sur l’écran d’accueil ». Sur Android, utilise « Installer l’application » ou « Ajouter à l’écran d’accueil » dans le menu du navigateur.</p><p>Charge l’application une première fois avec Internet et attends « Prêt pour le hors-ligne ». Elle peut ensuite fonctionner sans réseau. Les données restent dans ce navigateur : pas de synchronisation entre amis. Effacer les données du site peut supprimer l’historique.</p><button class="primary" data-action="close">Compris</button>`);}
function showHistory(id){const g=db.history.find(g=>g.id===id);if(!g)return;modal(`<span class="eyebrow">${date(g.finishedAt)} · ${g.target} points</span><h2>Le récap.</h2>${g.players.slice().sort((a,b)=>b.score-a.score).map(p=>`<div class="player-score"><span class="name">${esc(p.name)}${p.id===g.winner?' · Victoire':''}<small>${p.throws} lancers · ${p.kills} RàZ</small></span><strong>${p.score}</strong></div>`).join('')}<details><summary class="textbtn">Les ${g.log.length} lancers</summary>${g.log.map(d=>`<div class="feed-item"><span>M${d.round} · ${esc(d.player)}<br>${d.kind==='rim'?'Bordure':d.kind==='ground'?'Au sol':d.kind==='miss'?'Raté':`${d.multiplier} × ${d.base}`}${d.victims.length?` · ${esc(d.victims.join(', '))} à zéro`:''}</span><b>${d.before} ${d.overflow?'−':'+'} ${d.points} = ${d.after}</b></div>`).join('')}</details><button class="primary" data-action="close">Fermer</button>`);}
function dataDialog(){modal('<h2>Les souvenirs du club.</h2><p>Joueurs, parties et classement sont sauvegardés sur cet appareil. Exporte une copie pour les conserver ou les transférer.</p><button class="primary" data-action="export">Exporter la sauvegarde</button><p><label class="secondary" style="display:block;text-align:center;cursor:pointer">Importer une sauvegarde<input id="import" type="file" accept="application/json,.json" class="hide"></label></p><p class="hint">L’import remplace les données de cet appareil après confirmation.</p><button class="textbtn" data-action="close">Fermer</button>');}
let importCandidate;
function validateBackup(x){if(!x||x.version!==1||!Array.isArray(x.players)||!Array.isArray(x.history)||!Array.isArray(x.undo)||x.players.length>10000||x.history.length>10000)throw Error('Format non reconnu.');for(const p of x.players)if((typeof p.id!=='string'||!/^[-a-zA-Z0-9_]+$/.test(p.id))||typeof p.name!=='string'||p.name.length>100)throw Error('Joueur invalide.');if(new Set(x.players.map(p=>p.id)).size!==x.players.length)throw Error('Joueurs dupliqués.');for(const g of [...x.history,...x.undo,...(x.game?[x.game]:[])]){if(!g||![150,321,501].includes(g.target)||!Array.isArray(g.players)||!g.players.length||!Number.isInteger(g.current)||g.current<0||g.current>=g.players.length||!Number.isInteger(g.round)||g.round<1||!Array.isArray(g.darts)||g.darts.length>3||!Array.isArray(g.log)||(typeof g.id!=='string'||!/^[-a-zA-Z0-9_]+$/.test(g.id))||!g.challenge||typeof g.challenge.exercise!=='string'||![.5,1,2].includes(g.challenge.multiplier)||!Number.isInteger(g.challenge.cap)||g.challenge.cap<0||!Number.isFinite(g.turnPoints))throw Error('Partie invalide.');for(const p of g.players)if((typeof p.id!=='string'||!/^[-a-zA-Z0-9_]+$/.test(p.id))||typeof p.name!=='string'||!Number.isInteger(p.score)||p.score<0||p.score>g.target||![p.kills,p.hits,p.throws].every(n=>Number.isInteger(n)&&n>=0))throw Error('Score invalide.');if(g.winner&&!g.players.some(p=>p.id===g.winner))throw Error('Gagnant invalide.');for(const d of [...g.darts,...g.log])if(!d||typeof d.player!=='string'||!Array.isArray(d.victims)||!d.victims.every(n=>typeof n==='string')||![d.before,d.after,d.points].every(Number.isFinite))throw Error('Lancer invalide.');if(g.pendingChallenge&&(typeof g.pendingChallenge.player!=='string'||typeof g.pendingChallenge.exercise!=='string'||!Number.isFinite(g.pendingChallenge.repetitions)))throw Error('Défi invalide.');}return x;}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.player!==undefined)roster[+t.dataset.player].name=t.value;if(t.id==='custom-exercise')challenge.exercise=t.value.trim()||'Exercice libre';if(t.id==='cap'){challenge.cap=Math.max(0,Math.min(1000,Math.floor(+t.value||0)));}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='challenge-enabled'){challenge.enabled=t.checked;render();}if(t.id==='exercise'){challenge.exercise=t.value==='custom'?'Exercice libre':t.value;render();}if(t.id==='intensity'){challenge.multiplier=+t.value;render();}if(t.id==='import'&&t.files[0]){try{if(t.files[0].size>20*1024*1024)throw Error('Fichier trop volumineux (20 Mo maximum).');importCandidate=validateBackup(JSON.parse(await t.files[0].text()));modal(`<h2>Remplacer tes données ?</h2><p>Cette sauvegarde contient ${importCandidate.players.length} joueurs et ${importCandidate.history.length} parties terminées. Tes données actuelles seront remplacées.</p><div class="modal-actions"><button class="secondary" data-action="close">Annuler</button><button class="primary" data-action="confirm-import">Importer</button></div>`);}catch(err){notify('Import impossible : '+err.message);}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.view){view=d.view;render();return;}if(d.target){target=+d.target;render();return;}if(d.multi){multi=+d.multi;render();return;}if(d.remove!==undefined){roster.splice(+d.remove,1);render();return;}if(d.saved){const p=db.players.find(p=>p.id===d.saved);const blank=roster.findIndex(p=>!p.name.trim());if(blank>=0)roster[blank]=clone(p);else roster.push(clone(p));render();return;}if(d.hit){play({base:+d.hit,multiplier:multi});return;}if(d.bull){play({base:25,multiplier:+d.bull});return;}if(d.kind){play({kind:d.kind});return;}if(d.history){showHistory(d.history);return;}switch(d.action){case'home':view=db.game?'game':'setup';render();break;case'add-player':roster.push({id:crypto.randomUUID(),name:''});render();$(`[data-player="${roster.length-1}"]`).focus();break;case'start':start();break;case'next':try{const next=nextTurn(db.game);snapshot();db.game=next;multi=1;save();render();window.scrollTo({top:0,behavior:'smooth'});}catch(err){notify(err.message);}break;case'undo':case'undo-win':undo();break;case'new':newGame();break;case'abandon':resetSetup();break;case'close':closeModal();break;case'winner':showWinner();break;case'challenge':showChallenge();break;case'finish-challenge':case'skip-challenge':db.game.pendingChallenge=null;closeModal();save();render();break;case'rematch':resetSetup();start();break;case'rules':rules();break;case'data':dataDialog();break;case'export':{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`zero-club-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'confirm-import':if(importCandidate){db=clone(importCandidate);importCandidate=null;storageError=false;view=db.game?'game':'ranking';save();closeModal();render();notify('Sauvegarde importée.');}break;}});
render();
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(async()=>{const cache=await caches.open('zero-club-v1');offlineReady=await cache.match('./index.html')!==undefined;if(offlineReady&&$('#offline-status'))$('#offline-status').textContent='Prêt pour le hors-ligne';}).catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Hors-ligne non disponible';});}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_darts_game',title:'Lire la partie de fléchettes',description:'Lire les scores et le joueur actif sans modifier la partie.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>db.game?{target:db.game.target,currentPlayer:db.game.players[db.game.current].name,players:db.game.players.map(p=>({name:p.name,score:p.score})),dart:db.game.darts.length,winner:db.game.winner}:{status:'no_game'}})).catch(()=>{});}catch{}}
